import { cn } from "@repo/ui/lib/utils"
import { PIXEL_SCENES } from "./pixel-himalaya-data"

/**
 * Pixel-art Nepal: Himalayan peaks with snow, a pixel-step sky, prayer flags on a Boudhanath-like stupa, a pagoda and
 * Kathmandu rooftops, terraced fields. The rectangles are generated by `scripts/pixel-himalaya.mts` (seeded, so the
 * output is stable) into `pixel-himalaya-data.ts`; nothing is computed here. Keep it a Server Component: the data for
 * all three variants then stays on the server and only the chosen SVG reaches the page.
 *
 * - `panel`: portrait, for the auth side panel.
 * - `hero`: wide, with sky, for a page header.
 * - `strip`: wide and short, no sky (transparent), for a band above a footer or below a hero.
 *
 * The SVG scales to its box (`preserveAspectRatio="xMidYMid slice"`), so give it a size with `className`.
 */
export function PixelHimalaya({ className, variant }: { className?: string; variant: "panel" | "hero" | "strip" }) {
    const scene = PIXEL_SCENES[variant]
    return (
        <svg
            viewBox={`0 0 ${scene.w} ${scene.h}`}
            preserveAspectRatio="xMidYMid slice"
            shapeRendering="crispEdges"
            role="img"
            aria-label="Pixel illustration of the Himalaya above Kathmandu, with a stupa, prayer flags, a pagoda and terraced fields"
            className={cn("block h-auto w-full", className)}
        >
            {scene.layers.map(([cls, d]) => (
                <path key={cls} className={cls} d={d} />
            ))}
        </svg>
    )
}
